from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Loop through the input string to identify and extract each group of nested parentheses
    groups = []
    current_group = ""
    stack = []

    for char in paren_string:
        if char == "(":
            stack.append("(")
            current_group += char
        elif char == ")" and stack:
            stack.pop()
            current_group += char
            if not stack:
                groups.append(current_group)
                current_group = ""

    # Step 3 & 4: Check if each group of parentheses is balanced and separate the group into a separate string
    result = [group for group in groups if is_balanced(group)]

    return result

def is_balanced(group: str) -> bool:
    stack = []

    for char in group:
        if char == "(":
            stack.append("(")
        elif char == ")" and stack:
            stack.pop()
        else:
            return False

    return len(stack) == 0

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

